-- AF-01 Family Circle. The consumer contract is JSON-only; health data stays
-- behind these authenticated SECURITY DEFINER RPCs.
create table if not exists public.family_dependents (id uuid primary key default gen_random_uuid(), caregiver_user_id uuid not null references auth.users(id) on delete cascade, dependent_user_id uuid references auth.users(id) on delete set null, display_name text not null check(char_length(trim(display_name)) between 1 and 100), relationship text not null check(relationship in ('parent','child','sibling','spouse','other')), date_of_birth date, avatar_color text, dependent_email text, invite_token uuid unique, status text not null default 'active' check(status in ('invited','active','paused','revoked')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(caregiver_user_id,dependent_user_id));
create table if not exists public.family_dependent_scopes (dependent_id uuid not null references public.family_dependents(id) on delete cascade, scope text not null check(scope in ('meds_set','meds_view','adherence_view','workouts_set','workouts_view','period_signals','period_calendar')), granted_at timestamptz not null default now(), primary key(dependent_id,scope));
create table if not exists public.family_guardian_read_audit (id bigint generated by default as identity primary key, dependent_id uuid not null references public.family_dependents(id) on delete cascade, caregiver_user_id uuid not null references auth.users(id) on delete cascade, data_layer text not null check(data_layer in ('adherence','cycle','meds','workouts')), read_at timestamptz not null default now());
create index if not exists family_dependents_caregiver_idx on public.family_dependents(caregiver_user_id,status);
create index if not exists family_dependents_user_idx on public.family_dependents(dependent_user_id,status);
create index if not exists family_guardian_read_audit_dependent_idx on public.family_guardian_read_audit(dependent_id,read_at desc);
alter table public.family_dependents enable row level security; alter table public.family_dependent_scopes enable row level security; alter table public.family_guardian_read_audit enable row level security;
revoke all on public.family_dependents,public.family_dependent_scopes,public.family_guardian_read_audit from anon,authenticated;

create or replace function public.get_my_dependents() returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_premium boolean:=false;v_limit int; begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if; begin select coalesce(public.period_user_has_premium(v_me),false) into v_premium;exception when undefined_function then v_premium:=false;end;v_limit:=case when v_premium then 10 else 2 end;return jsonb_build_object('limit',v_limit,'is_premium',v_premium,'dependents',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'display_name',d.display_name,'relationship',d.relationship,'date_of_birth',d.date_of_birth,'avatar_color',d.avatar_color,'status',d.status,'is_profile_only',d.dependent_user_id is null,'scopes',coalesce((select jsonb_agg(s.scope order by s.scope) from public.family_dependent_scopes s where s.dependent_id=d.id),'[]'::jsonb)) order by d.created_at desc) from public.family_dependents d where d.caregiver_user_id=v_me),'[]'::jsonb));end $$;
create or replace function public.get_my_guardian_links() returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;return jsonb_build_object('links',coalesce((select jsonb_agg(jsonb_build_object('dependent_id',d.id,'caregiver_user_id',d.caregiver_user_id,'status',d.status,'scopes',coalesce((select jsonb_agg(s.scope order by s.scope) from public.family_dependent_scopes s where s.dependent_id=d.id),'[]'::jsonb)) order by d.created_at desc) from public.family_dependents d where d.dependent_user_id=v_me),'[]'::jsonb));end $$;
create or replace function public.add_dependent(p_display_name text,p_relationship text,p_date_of_birth date default null,p_avatar_color text default null,p_dependent_email text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_user uuid;v_id uuid;v_premium boolean:=false;v_limit int;v_token uuid;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_relationship not in ('parent','child','sibling','spouse','other') or char_length(trim(coalesce(p_display_name,''))) not between 1 and 100 then raise exception 'Invalid dependent' using errcode='22023';end if;begin select coalesce(public.period_user_has_premium(v_me),false) into v_premium;exception when undefined_function then v_premium:=false;end;v_limit:=case when v_premium then 10 else 2 end;if (select count(*) from public.family_dependents where caregiver_user_id=v_me and status<>'revoked')>=v_limit then raise exception 'Family Circle limit reached' using errcode='P0001';end if;if nullif(trim(p_dependent_email),'') is not null then select id into v_user from auth.users where lower(email)=lower(trim(p_dependent_email)) and is_sso_user=false limit 1;end if;v_token:=case when v_user is null and nullif(trim(p_dependent_email),'') is not null then gen_random_uuid() else null end;insert into public.family_dependents(caregiver_user_id,dependent_user_id,display_name,relationship,date_of_birth,avatar_color,dependent_email,invite_token,status) values(v_me,v_user,trim(p_display_name),p_relationship,p_date_of_birth,nullif(trim(p_avatar_color),''),nullif(lower(trim(p_dependent_email)),''),v_token,case when v_token is null then 'active' else 'invited' end) returning id into v_id;return jsonb_build_object('ok',true,'id',v_id,'status',case when v_token is null then 'active' else 'invited' end,'invite_token',v_token);end $$;
create or replace function public.claim_dependent_profile(p_invite_token uuid) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_id uuid;v_owner uuid;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;select id,caregiver_user_id into v_id,v_owner from public.family_dependents where invite_token=p_invite_token and status='invited' for update;if v_id is null then raise exception 'Invitation not found or expired' using errcode='P0002';end if;update public.family_dependents set dependent_user_id=v_me,status='active',invite_token=null,updated_at=now() where id=v_id;return jsonb_build_object('ok',true,'dependent_id',v_id,'caregiver_user_id',v_owner);end $$;
create or replace function public.set_dependent_scope(p_dependent_id uuid,p_scope text,p_grant boolean) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_scope not in ('meds_set','meds_view','adherence_view','workouts_set','workouts_view','period_signals','period_calendar') then raise exception 'Invalid scope' using errcode='22023';end if;if not exists(select 1 from public.family_dependents d where d.id=p_dependent_id and d.caregiver_user_id=v_me and d.status<>'revoked') then raise exception 'Not authorized' using errcode='42501';end if;if p_grant then insert into public.family_dependent_scopes(dependent_id,scope) values(p_dependent_id,p_scope) on conflict do nothing;else delete from public.family_dependent_scopes where dependent_id=p_dependent_id and scope=p_scope;end if;return jsonb_build_object('ok',true);end $$;
create or replace function public.set_dependent_status(p_dependent_id uuid,p_status text) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_status not in ('invited','active','paused','revoked') then raise exception 'Invalid status' using errcode='22023';end if;update public.family_dependents set status=p_status,updated_at=now() where id=p_dependent_id and caregiver_user_id=v_me;if not found then raise exception 'Not authorized' using errcode='42501';end if;return jsonb_build_object('ok',true);end $$;
create or replace function public.get_dependent_adherence_summary(p_dependent_id uuid,p_days int default 30) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_target uuid;v_status text;v_allowed boolean;v_taken int;v_missed int;v_skipped int;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_days<1 or p_days>90 then raise exception 'Days must be between 1 and 90' using errcode='22023';end if;select dependent_user_id,status into v_target,v_status from public.family_dependents where id=p_dependent_id and caregiver_user_id=v_me;select exists(select 1 from public.family_dependent_scopes where dependent_id=p_dependent_id and scope='adherence_view') into v_allowed;if v_target is null or v_status<>'active' or not v_allowed then return jsonb_build_object('ok',false,'reason','sharing_paused');end if;select count(*) filter(where status::text='taken'),count(*) filter(where status::text='missed'),count(*) filter(where status::text='skipped') into v_taken,v_missed,v_skipped from public.medication_adherence where user_id=v_target and scheduled_time>=now()-(p_days||' days')::interval;insert into public.family_guardian_read_audit(dependent_id,caregiver_user_id,data_layer) values(p_dependent_id,v_me,'adherence');return jsonb_build_object('ok',true,'days',p_days,'taken',coalesce(v_taken,0),'missed',coalesce(v_missed,0),'skipped',coalesce(v_skipped,0),'adherence_pct',case when coalesce(v_taken,0)+coalesce(v_missed,0)+coalesce(v_skipped,0)=0 then null else round(100.0*coalesce(v_taken,0)/(coalesce(v_taken,0)+coalesce(v_missed,0)+coalesce(v_skipped,0)),1) end);end $$;
create or replace function public.get_guardian_read_audit(p_dependent_id uuid) returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if not exists(select 1 from public.family_dependents d where d.id=p_dependent_id and d.dependent_user_id=v_me) then raise exception 'Not authorized' using errcode='42501';end if;return jsonb_build_object('reads',coalesce((select jsonb_agg(jsonb_build_object('data_layer',a.data_layer,'caregiver_user_id',a.caregiver_user_id,'read_at',a.read_at) order by a.read_at desc) from public.family_guardian_read_audit a where a.dependent_id=p_dependent_id),'[]'::jsonb));end $$;
revoke all on function public.get_my_dependents(),public.get_my_guardian_links(),public.add_dependent(text,text,date,text,text),public.claim_dependent_profile(uuid),public.set_dependent_scope(uuid,text,boolean),public.set_dependent_status(uuid,text),public.get_dependent_adherence_summary(uuid,int),public.get_guardian_read_audit(uuid) from public,anon;
grant execute on function public.get_my_dependents(),public.get_my_guardian_links(),public.add_dependent(text,text,date,text,text),public.claim_dependent_profile(uuid),public.set_dependent_scope(uuid,text,boolean),public.set_dependent_status(uuid,text),public.get_dependent_adherence_summary(uuid,int),public.get_guardian_read_audit(uuid) to authenticated,service_role;
notify pgrst,'reload schema';
